      for (const e of (daftar || []).filter(e => e.i >= i0 && e.i < END).sort((a, b) => a.i - b.i)) per.set(e.jenis, e);
      const isi = [...per.values()].sort((a, b) => b.i - a.i).slice(0, 3).sort((a, b) => a.i - b.i);
